/* ============================================================
   DOI_MATL_RESC  ←  202608 엑셀 적재
   DB : 도우제조원가시스템 (10.100.40.17,14233)
   행 : 278행
   엑셀: 08월 재고수불부(260910).xlsx / 시트 '재고금액(202608)' R4~R281 (R3 TOTAL 제외)
   엑셀 41개 컬럼이 DB 4~44번째 컬럼에 위치 1:1 대응
   * API 적재분은 금액/키가 모두 일치했으나 중분류 278행 전량 NULL이었음
     (스테이징 컬럼명 오타 UMItmeClassMName). 중분류는 UP_DOI_MAT_AMT의
     원가자재분류(약액/필름/원장) 파생 입력이라 결산 결과가 달라짐.
   실행: 검증 통과 시 자동 COMMIT, 실패 시 자동 ROLLBACK
   ============================================================ */
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;

DECLARE @before INT = (SELECT COUNT(*) FROM [DOI_MATL_RESC] WHERE [YYYYMM]='202608' AND [SITE]='HQ' AND [SEL_CODE]='ACTUAL');
DELETE FROM [DOI_MATL_RESC] WHERE [YYYYMM]='202608' AND [SITE]='HQ' AND [SEL_CODE]='ACTUAL';



/* ---------- 검증 ---------- */
DECLARE @ok BIT = 1, @msg NVARCHAR(2000) = N'';
DECLARE @after INT = (SELECT COUNT(*) FROM [DOI_MATL_RESC] WHERE [YYYYMM]='202608' AND [SITE]='HQ' AND [SEL_CODE]='ACTUAL');
IF @after <> 278 BEGIN SET @ok=0; SET @msg=@msg+N'행수 278 기대, 실제 '+CAST(@after AS NVARCHAR(20))+N'; '; END
IF ABS(ISNULL((SELECT SUM(기초금액) FROM DOI_MATL_RESC WHERE YYYYMM='202608'),0) - 2665212610) > 1 BEGIN SET @ok=0; SET @msg=@msg+N'기초금액 불일치(기대 2665212610, 실제 '+CAST(ISNULL((SELECT SUM(기초금액) FROM DOI_MATL_RESC WHERE YYYYMM='202608'),0) AS NVARCHAR(40))+N'); '; END
IF ABS(ISNULL((SELECT SUM(입고금액) FROM DOI_MATL_RESC WHERE YYYYMM='202608'),0) - 6175298625) > 1 BEGIN SET @ok=0; SET @msg=@msg+N'입고금액 불일치(기대 6175298625, 실제 '+CAST(ISNULL((SELECT SUM(입고금액) FROM DOI_MATL_RESC WHERE YYYYMM='202608'),0) AS NVARCHAR(40))+N'); '; END
IF ABS(ISNULL((SELECT SUM(출고금액) FROM DOI_MATL_RESC WHERE YYYYMM='202608'),0) - 6489808270) > 1 BEGIN SET @ok=0; SET @msg=@msg+N'출고금액 불일치(기대 6489808270, 실제 '+CAST(ISNULL((SELECT SUM(출고금액) FROM DOI_MATL_RESC WHERE YYYYMM='202608'),0) AS NVARCHAR(40))+N'); '; END
IF ABS(ISNULL((SELECT SUM(재고금액) FROM DOI_MATL_RESC WHERE YYYYMM='202608'),0) - 2350702965) > 1 BEGIN SET @ok=0; SET @msg=@msg+N'재고금액 불일치(기대 2350702965, 실제 '+CAST(ISNULL((SELECT SUM(재고금액) FROM DOI_MATL_RESC WHERE YYYYMM='202608'),0) AS NVARCHAR(40))+N'); '; END
IF ABS(ISNULL((SELECT COUNT(*) FROM DOI_MATL_RESC WHERE YYYYMM='202608' AND ISNULL(중분류,'')<>''),0) - 278) > 0 BEGIN SET @ok=0; SET @msg=@msg+N'중분류채워진행수 불일치(기대 278, 실제 '+CAST(ISNULL((SELECT COUNT(*) FROM DOI_MATL_RESC WHERE YYYYMM='202608' AND ISNULL(중분류,'')<>''),0) AS NVARCHAR(40))+N'); '; END

IF @ok = 1
BEGIN
  COMMIT;
  SELECT N'DOI_MATL_RESC 적재 완료' AS 결과, @before AS 삭제전행수, @after AS 적재행수;
END
ELSE
BEGIN
  ROLLBACK;
  SELECT N'DOI_MATL_RESC 검증 실패 — 원상복구' AS 결과, @msg AS 사유;
END
GO